seq = open('region.fasta').read().split('\n',1)[1].replace('\n','').strip()
comp = {'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[x] for x in reversed(s))
L=len(seq)

def tostrand(s, strand):
    return s if strand=='+' else rc(s)

# stem-loop search: for each strand, find inverted repeats with stem>=4, loop 3-12
def hairpins(s, minstem=4, minloop=3, maxloop=12):
    res=[]
    n=len(s)
    for i in range(n):
        for stemlen in range(minstem, 9):
            left = s[i:i+stemlen]
            rl = rc(left)
            # look for rl downstream starting between i+stemlen+minloop and +stemlen+maxloop
            for gap in range(minloop, maxloop+1):
                j = i+stemlen+gap
                if j+stemlen>n: break
                if s[j:j+stemlen]==rl:
                    res.append((i, j+stemlen, stemlen, gap))
    return res

# slippery sequences: -1 type heptamer-ish (X XXY YYZ) approximated by runs like AAAA/AAAG
def slipp(x):
    hits=[]
    for m in re.finditer(r'[AT]{5,}[AG]?', x):
        hits.append((m.start(),m.end(),m.group()))
    return hits

