def rc(s): return ''.join(comp[x] for x in reversed(s))
L=len(seq)

def hairpins(s, minstem=5, minloop=3, maxloop=14, maxstem=14):
    res=[]
    n=len(s)
    for i in range(n):
        for stemlen in range(maxstem, minstem-1, -1):
            left = s[i:i+stemlen]
            if 'N' in left: continue
            rl = rc(left)
            for gap in range(minloop, maxloop+1):
                j = i+stemlen+gap
                if j+stemlen>n: break
                if s[j:j+stemlen]==rl:
                    res.append((i, j+stemlen, stemlen, gap))
    return res

for strand,s in [('+',seq),('-',rc(seq))]:
    hs = hairpins(s)
    # deduplicate by loosely overlapping
    hs.sort(key=lambda x:-(x[2]))
    print('=== strand',strand, 'num hairpins', len(hs))
    shown=[]
    for (a,b,st,loop) in hs:
        if any(not(b< x[0]-5 or a> x[1]+5) for x in shown): continue
        shown.append((a,b,st,loop))
        if strand=='+':
            print(f'  stem{st} loop{loop}  pos {a}-{b}  {s[a:a+st]}..{s[b-st:b]}')
        else:
            print(f'  stem{st} loop{loop}  pos(rev) {a}-{b}  fwd({L-b}-{L-a})  {s[a:a+st]}..{s[b-st:b]}')
        if len(shown)>25: break
